WITH dim_totals AS (SELECT d.country, d.city, COUNT(*) AS num_rows, ROUND(AVG(src.monthly_fee), 2) AS avg_monthly_fee FROM subscriptions src LEFT JOIN customers d ON src.customer_id = d.id GROUP BY d.country, d.city) SELECT country, city, num_rows, CASE WHEN country RLIKE '^(US|DE)$' THEN 'OTHER_ZONE' WHEN country RLIKE '^(TH|SG)$' THEN 'GROUP_B' ELSE 'CORE' END AS country_zone FROM dim_totals ORDER BY city NULLS FIRST
